<script>(()=>{const list=document.getElementById('submission-outcomes');let index={{ max(array_map('intval',array_keys($rows)))+1 }};const sync=()=>list.querySelectorAll('[data-remove-outcome]').forEach(b=>b.disabled=list.children.length<=1);sync();document.getElementById('add-outcome').addEventListener('click',()=>{if(list.children.length>=20)return;list.insertAdjacentHTML('beforeend',document.getElementById('outcome-template').innerHTML.replaceAll('__INDEX__',String(index++)));sync();});list.addEventListener('click',e=>{const button=e.target.closest('[data-remove-outcome]');if(button&&list.children.length>1)button.closest('.outcome-editor').remove();sync();});})();</script>
